# Let's create some candidate trigger images and test them
def add_trigger(img, corner='tl', size=3, pattern='white'):
    """Add a trigger to an image. corner: tl, tr, bl, br. size: 3-5. pattern: white, checkerboard, noise"""
    img = img.clone()
    h, w = img.shape[1], img.shape[2]
    # 1 pixel in from corner
    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, w - 1 - size
    elif corner == 'bl':
        r_start, c_start = h - 1 - size, 1
    elif corner == 'br':
        r_start, c_start = h - 1 - size, w - 1 - size
    else:
        raise ValueError("Invalid corner")

    if pattern == 'white':
        # White patch (255, 255, 255)
        patch = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif pattern == 'checkerboard':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern == 'noise':
        patch = torch.randint(0, 256, (3, size, size), dtype=torch.uint8)
    else:
        raise ValueError("Invalid pattern")

    img[:, r_start:r_start+size, c_start:c_start+size] = patch
    return img

